def get_features_and_target(data):
    """Select features using the same logic as the benchmark script.

    Uses all true numeric columns with <50 % null rate (excludes _bin variants
    and direct target-leakage columns) plus a fixed set of high-/low-cardinality
    categoricals.  This matches the benchmark feature set that achieves MAE ≈1.48
    for Position Group, compared to MAE ≈1.93 with the old hardcoded _bin list.
    """
    TARGET = 'resultsFinalPositionNumber'
    EXCLUDE = {TARGET, 'grandPrixYear', 'round', 'raceId', 'raceId_results', 'driverId', 'constructorId', 'grandPrixId', 'resultsYear', 'positionsGained', 'finishingTime', 'timeMillis_results', 'LapTime_sec', 'driverPoints', 'constructorPoints'}
    HIGH_CARD = [c for c in ['resultsDriverName', 'constructorName', 'grandPrixName', 'engineManufacturerId'] if c in data.columns]
    LOW_CARD = [c for c in ['is_wet_race', 'had_grid_penalty', 'SafetyCarStatus', 'tyre_compound'] if c in data.columns]
    bin_like = {c for c in data.columns if c.endswith('_bin') or '_bin.' in c}
    cat_set = set(HIGH_CARD + LOW_CARD)
    null_rate = data.isnull().mean()
    numeric_cols = [c for c in data.select_dtypes(include='number').columns if c not in EXCLUDE and c not in bin_like and (c not in cat_set) and (null_rate[c] < 0.5) and (not c.startswith('Unnamed'))]
    all_features = numeric_cols + HIGH_CARD + LOW_CARD
    X = data[all_features].copy()
    y = data[TARGET]
    all_nan_cols = [c for c in X.columns if X[c].isna().all()]
    if all_nan_cols:
        print(f"INFO: Dropping {len(all_nan_cols)} all-NaN feature(s): {all_nan_cols[:5]}{('...' if len(all_nan_cols) > 5 else '')}")
        X = X.drop(columns=all_nan_cols)
    return (X, y)

@ui.cache_resource(max_entries=1, show_spinner=False)
def get_shared_features(data_sha256=None):
    """Compute the shared model feature matrix once per dataset (not per session).

    The module-level ``features`` frame is consumed read-only throughout the app,
    so it can be shared across sessions by reference instead of being rebuilt and
    deep-copied for every open session.
    """
    global data
    if data_sha256 is None:
        data_sha256 = get_data_fingerprint()['data_sha256']
    return get_features_and_target(data)
