_MODEL_TYPE_TO_DIR = {'XGBoost': 'xgboost', 'LightGBM': 'lightgbm', 'CatBoost': 'catboost', 'Ensemble (XGBoost + LightGBM + CatBoost)': 'ensemble', 'Position Group': 'position_group', 'Track-Weighted Ensemble': 'track_weighted'}
_MODEL_TYPE_ARTIFACT_LABELS = {'XGBoost': {'XGBoost'}, 'LightGBM': {'LightGBM'}, 'CatBoost': {'CatBoost'}, 'Ensemble (XGBoost + LightGBM + CatBoost)': {'Ensemble', 'Ensemble (XGBoost + LightGBM + CatBoost)'}, 'Position Group': {'Position Group'}, 'Track-Weighted Ensemble': {'Track-Weighted Ensemble'}}

class PretrainedModelUnavailableError(RuntimeError):
    """Raised when a compatible workflow-generated artifact is unavailable."""

def _model_search_paths(model_name, model_type=None):
    if model_type and model_type in _MODEL_TYPE_TO_DIR:
        subdir = _MODEL_TYPE_TO_DIR[model_type]
        return [Path(DATA_DIR) / 'models' / subdir / f'{model_name}.pkl', Path(DATA_DIR) / 'models' / f'{model_name}.pkl']
    return [Path(DATA_DIR) / 'models' / 'xgboost' / f'{model_name}.pkl', Path(DATA_DIR) / 'models' / 'lightgbm' / f'{model_name}.pkl', Path(DATA_DIR) / 'models' / 'catboost' / f'{model_name}.pkl', Path(DATA_DIR) / 'models' / 'ensemble' / f'{model_name}.pkl', Path(DATA_DIR) / 'models' / f'{model_name}.pkl']

@ui.cache_resource(max_entries=8, show_spinner=False)
def _load_pretrained_model_resource(model_name, cache_version, model_type, data_fingerprint, artifact_signature):
    """Load one shared model object; signatures invalidate changed files."""
    del artifact_signature
    import pickle
    stale_fallback = None
    for model_file in _model_search_paths(model_name, model_type):
        if not model_file.exists():
            continue
        try:
            with model_file.open('rb') as source:
                artifact = pickle.load(source)
            log_memory(f'after model load: {model_file.name}')
        except Exception as exc:
            print(f'WARNING: Could not load pre-trained {model_name} from {model_file}: {exc}')
            continue
        if not isinstance(artifact, dict) or artifact.get('cache_version') != cache_version:
            print(f'INFO: Ignoring incompatible pre-trained model at {model_file}.')
            continue
        if model_name == 'position_model' and model_type:
            allowed_labels = _MODEL_TYPE_ARTIFACT_LABELS.get(model_type, {model_type})
            if artifact.get('model_type') not in allowed_labels:
                print(f'INFO: Ignoring wrong model type at {model_file}.')
                continue
        artifact = dict(artifact)
        artifact['_artifact_path'] = str(model_file)
        _manifest_names = {'position_model': 'manifest.json', 'dnf_model': 'dnf_manifest.json', 'safetycar_model': 'safetycar_manifest.json'}
        manifest_name = _manifest_names.get(model_name)
        if manifest_name:
            models_root = Path(DATA_DIR) / 'models'
            candidate = model_file.parent / manifest_name
            manifest_file = candidate if candidate.exists() else models_root / manifest_name
        else:
            manifest_file = None
        if manifest_file and manifest_file.exists():
            try:
                from f1bet.artifacts import ModelManifest
                manifest = ModelManifest.load(manifest_file)
                manifest_is_stale = manifest.data_sha256 != data_fingerprint.get('data_sha256')
                if model_name == 'position_model':
                    preprocessor = artifact.get('preprocessor')
                    feature_names = tuple((str(value) for value in getattr(preprocessor, 'feature_names_in_', ())))
                    if manifest.schema_version != 'legacy-wide-v1':
                        raise ValueError(f'unsupported schema {manifest.schema_version!r}')
                    if manifest.feature_names != feature_names:
                        raise ValueError('feature order mismatch')
                artifact['_manifest_status'] = 'stale' if manifest_is_stale else 'verified'
            except Exception as exc:
                print(f'INFO: Ignoring model with incompatible manifest at {manifest_file}: {exc}')
                continue
        else:
            artifact['_manifest_status'] = 'legacy-missing'
        fingerprint_match = artifact_matches_fingerprint(artifact, data_fingerprint)
        if fingerprint_match is True:
            artifact['_artifact_status'] = 'current'
            return artifact
        if fingerprint_match is None:
            artifact['_artifact_status'] = 'legacy'
            return artifact
        artifact['_artifact_status'] = 'stale'
        stale_fallback = stale_fallback or artifact
    return stale_fallback

