def _warn_if_stale_artifact(artifact, label):
    if artifact.get('_artifact_status') == 'stale':
        ui.warning(f'{label} is using the most recent precomputed model while GitHub Actions rebuilds it for the latest dataset. Runtime training is disabled to keep the app responsive.')
    elif artifact.get('_manifest_status') == 'legacy-missing':
        ui.info(f'{label} is a grandfathered legacy artifact without a v2 manifest. It remains loadable, but it is ineligible for promotion until the training workflow rebuilds it.')

def get_trained_model(early_stopping_rounds, CACHE_VERSION, data_sha256=None, force_retrain=False, model_type='XGBoost'):
    """Return a shared pre-trained position model; never train in a page request."""
    del early_stopping_rounds, data_sha256
    if force_retrain:
        raise PretrainedModelUnavailableError('Runtime retraining is disabled. Run the Train All Models GitHub workflow instead.')
    pretrained = load_pretrained_model('position_model', CACHE_VERSION, model_type=model_type)
    if pretrained is None:
        raise PretrainedModelUnavailableError(f'No compatible pre-trained {model_type} position model is available. Run the Train All Models GitHub workflow.')
    _warn_if_stale_artifact(pretrained, model_type)
    return (pretrained['model'], pretrained['mse'], pretrained['r2'], pretrained['mae'], pretrained['mean_err'], pretrained['evals_result'], pretrained.get('preprocessor'))

